('OB-001','P07-M06','P07-T03','2026-10-16T07:40:00+05:30',array['sound','smell']::text[],'Knocking sound at startup for about 20 seconds, then settles. Slight burnt oil smell near crankcase. Was not there last week.','voice','P-07'),
('OB-002','P07-M09','P07-T01','2026-10-15T15:10:00+05:30',array['visual','performance']::text[],'Oil seepage below main cylinder, small puddle by end of shift. Pressure takes 8 to 10 seconds longer to build.','text','P-07'),
('OB-003','P07-M15','P07-T09','2026-10-14T11:25:00+05:30',array['visual']::text[],'Slight weeping at mechanical seal, few drops per hour.','text','P-07'),
('OB-004','P07-M30','P07-T05','2026-10-17T09:05:00+05:30',array['smell','sound']::text[],'Panel ke paas jalne ki smell aa rahi hai, contactor bhinbhina raha hai. Feeder 3 breaker tripped once this morning.','voice','P-07'),
('OB-005','P07-M16','P07-T10','2026-10-16T18:30:00+05:30',array['sound']::text[],'Running a bit funny today, not sure what.','text','P-07'),
('OB-006','P07-M08','P07-T07','2026-10-13T10:00:00+05:30',array['sound']::text[],'Belt squeal at start only, goes away in a minute.','text','P-07'),
('OB-101','P03-M03','P03-T01','2026-10-16T10:00:00+00:00',array['sound']::text[],'Motor body very hot near terminal box.','text','P-03'),
('OB-102','P12-M02','P12-T01','2026-10-16T10:00:00+00:00',array['sound']::text[],'Grinding noise from drive end bearing, housing hot to touch.','text','P-12'),
