insert into alerts (id,machine_id,created_at,trigger,risk_score,failure_mode,confidence,urgency,insufficient_evidence,evidence,reasoning,recommended_action,action_type,required_certifications,loto_required,assigned_technician,shadow_technician,proposed_window,spares_check,est_failure_cost_usd,est_intervention_cost_usd,guardrail_result,status,decided_by,decision_reason,source,prompt_version,plant_id) values
('AL-1001','P07-M03','2026-10-17T06:15:00+05:30','sensor_threshold',88,'bearing_wear',0.86,'P1',false,'[{"id": "E1", "type": "sensor", "text": "Vibration 6.10 mm/s vs 1.68 baseline (ISO 10816 alarm band 4.5 to 7.1)"}, {"id": "E2", "type": "sensor", "text": "Vibration rising 7 straight days, 2.71 to 6.10 mm/s"}, {"id": "E3", "type": "sensor", "text": "Temperature 74.6 C vs 59.4 C baseline (+15.2 C)"}, {"id": "E4", "type": "history", "text": "Bearing-type fault found on this asset in an earlier PM"}]'::jsonb,'Steady 7-day rise in vibration with matching temperature rise is the classic signature of progressive bearing wear on the gearbox output shaft. Pattern is not a spike. At current slope, vibration reaches the unacceptable band (above 7.1 mm/s) in about 2 days.','Replace output shaft bearing (22312) and change gear oil during Sunday planned shutdown. Apply LOTO. Laser-check alignment after fitting.','replace',array['Mechanical','LOTO']::text[],true,'P07-T01','P07-T07','{"line_id": "P07-L1", "date": "2026-10-18", "shift": "A", "window_type": "planned_shutdown", "production_loss_units": 0}'::jsonb,'[{"part_id": "SP-003", "name": "Spherical roller bearing 22312", "stock": 1, "min_level": 2, "status": "available_below_min", "action": "reserve 1, raise reorder"}, {"part_id": "SP-009", "name": "Gear oil ISO VG 320 (20L)", "stock": 5, "status": "available", "action": "reserve 1"}]'::jsonb,144000,1450,'{"pass": true, "checks": [{"rule": "schema_valid", "pass": true, "detail": "JSON matches schema v1"}, {"rule": "evidence_ids_exist", "pass": true, "detail": "E1 to E4 found"}, {"rule": "confidence_threshold", "pass": true, "detail": "0.86 >= 0.70"}, {"rule": "certification_match", "pass": true, "detail": "P07-T01 holds Mechanical + valid LOTO"}, {"rule": "loto_enforced", "pass": true, "detail": "LOTO step added to checklist"}, {"rule": "spares_checked", "pass": true, "detail": "Bearing in stock (below min)"}]}'::jsonb,'pending',null,null,'cached','triage-v1.0','P-07'),
('AL-1002','P07-M30','2026-10-17T09:12:00+05:30','technician_observation',82,'electrical_fault',0.78,'P1',false,'[{"id": "E1", "type": "observation", "text": "OB-004 (Mohan Iyer, 30 yrs): burning smell near panel, contactor buzzing (recorded in Hinglish)"}, {"id": "E2", "type": "observation", "text": "Feeder 3 breaker tripped once this morning"}, {"id": "E3", "type": "knowledge", "text": "KL-06: buzzing contactor + burnt insulation smell = overheating contacts or loose lug"}]'::jsonb,'Burning smell plus contactor chatter on a 1997 MCC matches the veteran knowledge entry for overheating contacts. MCC-3 feeds the whole of Line 3, so consequence is high.','Thermal scan and inspect feeder 3 contactor and lugs, replace contactor if pitted. HT-certified electrician only, full LOTO.','escalate',array['Electrical HT','LOTO']::text[],true,'P07-T02','P07-T12','{"line_id": "P07-L3", "date": "2026-10-17", "shift": "C", "window_type": "low_load", "production_loss_units": 2900}'::jsonb,'[{"part_id": "SP-012", "name": "Contactor 3P 40A", "stock": 5, "status": "available", "action": "reserve 1"}]'::jsonb,126000,900,'{"pass": false, "checks": [{"rule": "schema_valid", "pass": true, "detail": "JSON matches schema v1"}, {"rule": "evidence_ids_exist", "pass": true, "detail": "OB-004, KL-06 found"}, {"rule": "confidence_threshold", "pass": true, "detail": "0.78 >= 0.70"}, {"rule": "certification_match", "pass": false, "detail": "No Electrical HT technician on current shift A. Only P07-T02 (shift C) qualified."}, {"rule": "loto_enforced", "pass": true, "detail": "LOTO step added"}]}'::jsonb,'needs_review',null,null,'cached','triage-v1.0','P-07'),
('AL-1003','P07-M22','2026-10-16T14:02:00+05:30','sensor_threshold',12,'none',0.31,'none',false,'[{"id": "E1", "type": "sensor", "text": "Single reading 7.80 mm/s on 16 Oct, flagged as spike"}, {"id": "E2", "type": "sensor", "text": "Readings before and after within baseline (1.97 mm/s), flat 7-day trend"}]'::jsonb,'One-off sample with no trend and no temperature change. Most likely a transient (robot collision stop or sensor knock). Pulling the line would cost production for no likely gain.','No intervention. Keep monitoring; re-alert if 2 consecutive readings exceed 4.5 mm/s.','monitor','{}'::text[],false,null,null,null,'[]'::jsonb,0,0,'{"pass": false, "checks": [{"rule": "confidence_threshold", "pass": false, "detail": "0.31 < 0.70, alert suppressed"}, {"rule": "spike_filter", "pass": true, "detail": "Single-sample spike ignored"}]}'::jsonb,'suppressed','system','False-alarm filter','cached','triage-v1.0','P-07'),
('AL-1004','P07-M09','2026-10-15T15:30:00+05:30','technician_observation',64,'hydraulic_leak',0.81,'P2',false,'[{"id": "E1", "type": "observation", "text": "OB-002 (Ramesh Patil, 32 yrs): oil puddle under main cylinder"}, {"id": "E2", "type": "observation", "text": "Pressure build 8 to 10 s slower than normal"}, {"id": "E3", "type": "knowledge", "text": "KL-03: slow ram + pump whine = internal or external leak"}]'::jsonb,'Visible leak plus slower pressure build points to a failing cylinder seal. Press is criticality A but still producing; repair in the next changeover avoids an unplanned stop.','Replace main cylinder seal kit, inspect hoses, top up oil. LOTO and hydraulic pressure release required.','repair',array['Hydraulics','LOTO']::text[],true,'P07-T09','P07-T10','{"line_id": "P07-L1", "date": "2026-10-20", "shift": "B", "window_type": "changeover", "production_loss_units": 0}'::jsonb,'[{"part_id": "SP-007", "name": "Hydraulic cylinder seal kit 80mm", "stock": 3, "status": "available", "action": "reserved 1"}]'::jsonb,72000,620,'{"pass": true, "checks": [{"rule": "schema_valid", "pass": true, "detail": ""}, {"rule": "confidence_threshold", "pass": true, "detail": "0.81 >= 0.70"}, {"rule": "certification_match", "pass": true, "detail": "P07-T04 rejected: LOTO expired 30 Sep 2026. P07-T09 assigned (LOTO valid to 10 Nov 2026)."}, {"rule": "loto_enforced", "pass": true, "detail": ""}]}'::jsonb,'approved','Maintenance Planner','Agreed, use Tuesday changeover','cached','triage-v1.0','P-07'),
('AL-1005','P07-M06','2026-10-16T08:00:00+05:30','technician_observation',70,'bearing_wear',0.74,'P2',false,'[{"id": "E1", "type": "observation", "text": "OB-001 (Gurpreet Singh, 26 yrs): knocking at startup that settles, burnt oil smell"}, {"id": "E2", "type": "knowledge", "text": "KL-01: startup knock fading as oil warms = early big-end or main bearing wear"}]'::jsonb,'Startup knock that fades is the veteran signature for bearing wear with marginal lubrication on reciprocating compressors.','Change compressor oil, inspect main bearing clearance, replace bearing if play found.','replace',array['Mechanical','LOTO']::text[],true,'P07-T03','P07-T07','{"line_id": "P07-L1", "date": "2026-10-17", "shift": "A", "window_type": "run", "production_loss_units": 0, "note": "AC-2 covers air demand during repair"}'::jsonb,'[{"part_id": "SP-002", "name": "Bearing 6308-2Z", "stock": 5, "status": "available", "action": "reserved 1"}, {"part_id": "SP-010", "name": "Compressor oil (20L)", "stock": 4, "status": "available", "action": "reserved 1"}]'::jsonb,90000,540,'{"pass": true, "checks": [{"rule": "schema_valid", "pass": true, "detail": ""}, {"rule": "confidence_threshold", "pass": true, "detail": "0.74 >= 0.70"}, {"rule": "certification_match", "pass": true, "detail": ""}, {"rule": "loto_enforced", "pass": true, "detail": ""}]}'::jsonb,'approved','Plant Head','Go ahead','cached','triage-v1.0','P-07'),
('AL-1006','P07-M12','2026-10-17T07:30:00+05:30','sensor_threshold',74,'motor_overheating',0.82,'P2',false,'[{"id": "E1", "type": "sensor", "text": "Motor temperature 71.9 C vs 51.7 C baseline (+20.2 C)"}, {"id": "E2", "type": "sensor", "text": "Steady rise over 9 days, vibration only slightly up (2.71 mm/s)"}]'::jsonb,'Temperature rising without matching vibration suggests cooling or load issue rather than mechanical damage. Replacement servo motor is out of stock with 45-day lead time, so prevent failure first.','Clean motor fan and filter, check drive current and duty cycle settings. Raise urgent purchase order for spare servo motor.','repair',array['Electrical LV','LOTO']::text[],true,'P07-T06',null,'{"line_id": "P07-L2", "date": "2026-10-18", "shift": "C", "window_type": "changeover", "production_loss_units": 0}'::jsonb,'[{"part_id": "SP-015", "name": "Servo motor 2.2kW", "stock": 0, "status": "stockout", "action": "raise urgent PO, 45-day lead time"}]'::jsonb,108000,300,'{"pass": false, "checks": [{"rule": "schema_valid", "pass": true, "detail": ""}, {"rule": "confidence_threshold", "pass": true, "detail": "0.82 >= 0.70"}, {"rule": "certification_match", "pass": true, "detail": ""}, {"rule": "spares_checked", "pass": false, "detail": "Critical spare out of stock: procurement flagged"}]}'::jsonb,'pending',null,null,'cached','triage-v1.0','P-07'),
('AL-1007','P07-M16','2026-10-16T18:45:00+05:30','technician_observation',18,'unknown',0.35,'P3',true,'[{"id": "E1", "type": "observation", "text": "OB-005 (Kavya Reddy, trainee): ''running a bit funny'', no specific symptom"}]'::jsonb,'Note has no specific sound, smell, heat or location. Not enough to diagnose. Good learning moment: pair trainee with a veteran for a guided check.','Guided inspection by veteran with the trainee. Record specific symptoms using the capture checklist.','inspect',array['Mechanical']::text[],false,'P07-T01','P07-T10','{"line_id": "P07-L2", "date": "2026-10-19", "shift": "A", "window_type": "run", "production_loss_units": 0}'::jsonb,'[]'::jsonb,0,60,'{"pass": true, "checks": [{"rule": "insufficient_evidence_flag", "pass": true, "detail": "Model declined to guess"}]}'::jsonb,'pending',null,null,'cached','triage-v1.0','P-07'),
('AL-1008','P07-M18','2026-10-17T06:00:00+05:30','data_quality',30,'sensor_fault',0.9,'P3',true,'[{"id": "E1", "type": "sensor", "text": "No vibration or temperature data since 14 Oct (4 days)"}]'::jsonb,'Labeller condition cannot be confirmed while the sensor is offline. Keep its calendar PM until data returns.','Check sensor cable, connector and gateway. Keep scheduled PM until data restored.','inspect',array['Instrumentation']::text[],false,'P07-T08',null,'{"line_id": "P07-L2", "date": "2026-10-17", "shift": "A", "window_type": "run", "production_loss_units": 0}'::jsonb,'[{"part_id": "SP-023", "name": "Vibration sensor (IEPE)", "stock": 3, "status": "available", "action": "none yet"}]'::jsonb,0,40,'{"pass": true, "checks": [{"rule": "insufficient_evidence_flag", "pass": true, "detail": ""}]}'::jsonb,'pending',null,null,'cached','triage-v1.0','P-07'),
